#ifndef POTTERY_DETECTOR_H
#define POTTERY_DETECTOR_H
#include <stdint.h>
typedef struct pc_detector pc_detector;
typedef struct { int id; int hamming; float margin; double x[4]; double y[4]; } pc_tag;
pc_detector *pc_detector_create(void);
void pc_detector_destroy(pc_detector *detector);
// Caller owns pixels and output; no image is retained after this call.
int pc_detector_detect(pc_detector *detector, const uint8_t *pixels, int width, int height, int stride, pc_tag *output, int capacity);
// Synthetic test fixture generated by the same pinned family, not physical evidence.
int pc_render_test_tag(int id, uint8_t *pixels, int width, int height);
#endif
